shopify.query:
query AdsHeartbeatSep12LateOrderCounts {
  shop { id name ianaTimezone }
  allNew: ordersCount(query:"created_at:>='2026-09-12T20:41:48Z' created_at:<'2026-09-12T22:52:24Z'",limit:null) { count precision }
  webNonTest: ordersCount(query:"created_at:>='2026-09-12T20:41:48Z' created_at:<'2026-09-12T22:52:24Z' source_name:web test:false",limit:null) { count precision }
  paidWebNonTest: ordersCount(query:"created_at:>='2026-09-12T20:41:48Z' created_at:<'2026-09-12T22:52:24Z' source_name:web test:false financial_status:paid",limit:null) { count precision }
}
